from abc import ABCMeta, abstractmethod

import attr
import six
from typing import Optional

from .connection_details import SshServiceDetails
from .gnb.networkaddress import NetworkAddress


DEFAULT_MCC = '244'
DEFAULT_MNC = '09'


@attr.s(cmp=False)
class PCF(object):
    """
    Policy Control Function
    :param SshServiceDetails oam_ssh_connection_details: PCF ssh entry for management
    """
    oam_ssh_connection_details = attr.ib(type=SshServiceDetails)

    def __taf_contract_ssh__(self):
        return self.oam_ssh_connection_details.__taf_contract_ssh__()

@six.add_metaclass(ABCMeta)
class Core(object):

    @abstractmethod
    def __init__(self, mcc=None, mnc=None, pdns=None, pcf=None, **kwargs):
        self.mcc = mcc or DEFAULT_MCC
        self.mnc = mnc or DEFAULT_MNC
        self.pdns = pdns
        self.pcf = pcf


@attr.s(cmp=False)
class MME(object):
    """
    4G Core Mobility Management Entity
    :param SshServiceDetails oam_ssh_connection_details: MME ssh entry for management
    :param NetworkAddress s1: mme s1 address
    """
    oam_ssh_connection_details = attr.ib(type=SshServiceDetails)
    s1 = attr.ib(type=NetworkAddress)

    def __taf_contract_ssh__(self):
        return self.oam_ssh_connection_details.__taf_contract_ssh__()


@attr.s(cmp=False)
class AMF(object):
    """
    5G Core Access and Mobility Management Function
    :param SshServiceDetails oam_ssh_connection_details: AMF ssh entry for management
    :param NetworkAddress n2: amf N2 address
    """
    oam_ssh_connection_details = attr.ib(type=SshServiceDetails)
    n2 = attr.ib(type=NetworkAddress)

    def __taf_contract_ssh__(self):
        return self.oam_ssh_connection_details.__taf_contract_ssh__()


@six.add_metaclass(ABCMeta)
class Core4G(Core):
    pass


@six.add_metaclass(ABCMeta)
class Core5G(Core):
    pass


@attr.s(cmp=False)
class RealCore4GDetails(object):
    """
    4G real core featured parts
    :param Optional[MME] mme: Mobility Management Entity, MME object instance
    :param Optional[int] tac: Tracking area code that is supported by this instance of 4G core
    :param Optional[NetworkAddress] ntp: NTP address
    """
    mme = attr.ib(type=Optional[MME])
    tac = attr.ib(type=Optional[int], default=None)
    ntp = attr.ib(type=NetworkAddress, default=None)


@attr.s(cmp=False)
class RealCore5GDetails(object):
    """
    5G real core featured parts
    :param Optional[AMF] amf: Access and Mobility Management Function, AMF object instance
    :param Optional[int] tac: 5G extended tracking area code that is supported by this instance of 5G core
    """
    amf = attr.ib(type=Optional[AMF])
    tac = attr.ib(type=Optional[int], default=None)


class IPS(object):
    """
    Independent protocol simulator in real core.
    """

    def __init__(self, ssh_connection_details, **kwargs):
        """
        Create independent protocol simulator configuration object.

        :param SshServiceDetails ssh_connection_details: SSH login details for IPS
        """
        super(IPS, self).__init__(**kwargs)
        self.ssh_connection_details = ssh_connection_details

    def __taf_contract_ssh__(self):
        return self.ssh_connection_details.__taf_contract_ssh__()


class RealCore(Core):

    def __init__(self, four_g=None, five_g=None, ips=None, **kwargs):

        """
        real core

        :param Optional[RealCore4GDetails] four_g: 4G real core featured parts
        :param Optional[RealCore5GDetails] five_g: 5G real core featured parts
        :param Optional[IPS] ips: independent protocol simulator
        :param str mcc: Mobile Country Code - unique code identifying the country of given network,
        defaults to `244` standing for Finland
        :param str mnc: Mobile Network Code - unique number identifying the network used in combination with mcc,
        defaults to `09` standing for Nokia
        :param Optional[List[PDN]] pdns: PDN setting list
        :param Optional[PCF] pcf: Policy Control Function, PCF object instance
        """
        super(RealCore, self).__init__(**kwargs)
        self.four_g = four_g
        self.five_g = five_g
        self.ips = ips


class RealCore4G(Core4G):
    """
    RealCore4G is deprecated and replaced by RealCore, will be removed in future
    """
    def __init__(self, mcc=DEFAULT_MCC, mnc=DEFAULT_MNC):
        super(RealCore4G, self).__init__(mcc=mcc, mnc=mnc)


class RealCore5G(Core5G):
    """
        RealCore5G is deprecated and replaced by RealCore, will be removed in future
    """
    def __init__(self, mcc=DEFAULT_MCC, mnc=DEFAULT_MNC):
        super(RealCore5G, self).__init__(mcc=mcc, mnc=mnc)


class EPCSim(Core4G):
    DEFAULT_EDAEMON_PORT = 10000
    DEFAULT_EGATE_PORT = 20000

    def __init__(self, mme_ip, tac, default_ssh_connection_details,
                 mcc=DEFAULT_MCC, mnc=DEFAULT_MNC, dir_path=None,
                 cfg_filename=None, edaemon_port=None, egate_port=None):
        # type: (str, int, SshServiceDetails, str, str, Optional[str], Optional[str], Optional[int], Optional[int]) -> None
        """
        :param str mme_ip: address ip of Mobility Management Entity (core network architecture)
        :param str mcc: Mobile Country Code - unique code identifying the country of given network,
        defaults to `244` standing for Finland
        :param str mnc: Mobile Network Code - unique number identifying the network used in combination with mcc,
        defaults to `09` standing for Nokia
        NOTE: `09` is a different code than `009`, in NIDD distinguished by parameter `mncLength`
        that has either value 2 or 3.
        :param int tac: Tracking Area Code - accepts 3 digital values
        :param SshServiceDetails default_ssh_connection_details:
        :param Optional[str] dir_path:
        :param Optional[str] cfg_filename:
        :param Optional[int] edaemon_port: edaemon port used when running edaemon, default 10000
        :param Optional[int] egate_port: egate port used when running egate, default 20000
        """
        super(EPCSim, self).__init__(mcc=mcc, mnc=mnc)
        self.mme_ip = mme_ip
        self.tac = tac
        self.edaemon_port = edaemon_port or self.DEFAULT_EDAEMON_PORT
        self.egate_port = egate_port or self.DEFAULT_EGATE_PORT
        self.default_ssh_connection_details = default_ssh_connection_details
        self.dir_path = dir_path or '/opt/iphy/latest'
        self.cfg_filename = cfg_filename or 'config.lua'

    def __taf_contract_ssh__(self):
        return self.default_ssh_connection_details.__taf_contract_ssh__()


class LTEEmuCore(Core4G):
    def __init__(self, default_ssh_connection_details, dir_path, cfg_filename, mme_ip,
                 mcc=DEFAULT_MCC, mnc=DEFAULT_MNC, tac=None, edaemon_port=None, egate_port=None):
        # type: (SshServiceDetails, str, str, str, str, str, int, Optional[int], Optional[int]) -> None
        """
        :param SshServiceDetails default_ssh_connection_details: SshServiceDetails class instance object
        :param str dir_path:
        :param str cfg_filename:
        :param str mme_ip: address ip of Mobility Management Entity (core network architecture)
        :param str mcc: Mobile Country Code - unique code identifying the country of given network,
        defaults to `244` standing for Finland
        :param str mnc: Mobile Network Code - unique number identifying the network used in combination with mcc,
        defaults to `09` standing for Nokia
        NOTE: `09` is a different code than `009`, in NIDD distinguished by parameter `mncLength`
        that has either value 2 or 3.
        :param int tac: Tracking Area Code - accepts 3 digital values
        :param Optional[int] edaemon_port: edaemon port used when running edaemon
        :param Optional[int] egate_port: egate port used when running egate

        """
        super(LTEEmuCore, self).__init__(mcc=mcc, mnc=mnc)
        self.mme_ip = mme_ip
        self.edaemon_port = edaemon_port
        self.egate_port = egate_port
        self.tac = tac
        self.default_ssh_connection_details = default_ssh_connection_details
        self.dir_path = dir_path
        self.cfg_filename = cfg_filename

    def __taf_contract_ssh__(self):
        return self.default_ssh_connection_details.__taf_contract_ssh__()


class PrismaCore(Core4G):
    def __init__(self, lsu_s1_ssh_connection_details, tstm_s1_ssh_connection_details,
                 mcc=DEFAULT_MCC, mnc=DEFAULT_MNC):
        # type: (SshServiceDetails, SshServiceDetails, str, str) -> None
        """

        :param lsu_s1_ssh_connection_details: SshServiceDetails class instance object
        :param tstm_s1_ssh_connection_details: SshServiceDetails class instance object
        :param str mcc: Mobile Country Code - unique code identifying the country of given network,
        defaults to `244` standing for Finland
        :param str mnc: Mobile Network Code - unique number identifying the network used in combination with mcc,
        defaults to `09` standing for Nokia
        NOTE: `09` is a different code than `009`, in NIDD distinguished by parameter `mncLength`
        that has either value 2 or 3.
        """
        super(PrismaCore, self).__init__(mcc=mcc, mnc=mnc)
        self.lsu_s1_ssh_connection_details = lsu_s1_ssh_connection_details
        self.tstm_s1_ssh_connection_details = tstm_s1_ssh_connection_details
